      "Bash(ls *)",
      "Bash(cat *)",
      "Bash(grep *)",
      "Bash(touch *)",
      "Bash(streamlit run *)",
      "Bash(curl -sf http://localhost:8501/*)"
    ],
    "deny": [
      "Bash(rm -rf *)",
      "Bash(git push *)",
      "Write(data/*.csv)",
      "Edit(data/*.csv)"
    ]
